import type {RequestContext} from './context.ts';
export function createContext(value: string, userId: string): RequestContext {return {traceId:value,userId};}
export function forkContext(context: RequestContext, suffix: string): RequestContext {return {...context, traceId: context.traceId+'/'+suffix};}

import type {RequestContext} from './context.ts';
import {auditLabel} from './job-types.ts';
import type {Job} from './job-types.ts';
export function describeJob(job: Job, context: RequestContext) {return {requestId:job.requestId,trace:context.traceId,audit:auditLabel(job.requestId),name:job.name};}

import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0, audit0} from '../src/catalog/record0.ts';

describe('RequestContext rename regression tests', () => {
  test('end-to-end propagation through handle', () => {
    const trace = 'trace-test-123';
    const user = 'user-456';
    const job = {requestId: 'job-789', name: 'compute-task'};

    const result = handle(trace, user, job);

    // RequestContext has traceId and no requestId
    assert.equal(result.context.traceId, trace);
    assert.equal('requestId' in result.context, false);
    assert.equal(result.context.userId, user);

    // Middleware headers preserve wire key
    assert.equal(result.headers['x-request-id'], trace);

    // Logging output preserves wire/output key requestId
    assert.equal(result.logs.requestId, trace);
    assert.equal(result.logs.userId, user);

    // Response body output preserves wire/output key requestId
    assert.equal(result.body.requestId, trace);

    // Worker payload receives forked traceId with suffix
    assert.equal(result.body.payload.trace, `${trace}/worker`);

    // Unrelated Job.requestId and audit are preserved
    assert.equal(result.body.payload.requestId, job.requestId);
    assert.equal(result.body.payload.audit, 'job:' + job.requestId);
    assert.equal(result.body.payload.name, job.name);
  });

  test('context creation, forkContext suffixes, and non-mutation', () => {
    const root = createContext('base-trace', 'user-001');
    assert.equal(root.traceId, 'base-trace');
    assert.equal(root.userId, 'user-001');
    assert.equal('requestId' in root, false);

    const child = forkContext(root, 'stage-1');
    assert.equal(child.traceId, 'base-trace/stage-1');
    assert.equal(child.userId, 'user-001');
    assert.equal('requestId' in child, false);

    // Original context is not mutated
    assert.equal(root.traceId, 'base-trace');

    const grandchild = forkContext(child, 'stage-2');
    assert.equal(grandchild.traceId, 'base-trace/stage-1/stage-2');
    assert.equal(child.traceId, 'base-trace/stage-1');
  });

  test('unrelated Job identifier and auditLabel are unchanged', () => {
    const context = createContext('ctx-trace', 'worker-user');
    const job = {requestId: 'job-standalone-99', name: 'index-worker'};

    const jobDesc = describeJob(job, context);
    assert.equal(jobDesc.requestId, 'job-standalone-99');
    assert.equal(jobDesc.trace, 'ctx-trace');
    assert.equal(jobDesc.audit, 'job:job-standalone-99');
    assert.equal(jobDesc.name, 'index-worker');

    assert.equal(auditLabel('audit-test'), 'job:audit-test');
  });

  test('traceSummary in plugins preserves output with traceId propagation', () => {
    const context = createContext('plugin-trace', 'plugin-user');
    const summary = traceSummary(context);

    assert.equal(summary.length, 8);
    for (let i = 0; i < 8; i++) {
      assert.deepEqual(summary[i], {
        requestId: 'plugin-trace',
        tag: `plugin${i}`,
        user: 'plugin-user',
      });
    }
  });

  test('catalog modules RequestContext and requestId remain unchanged', () => {
    const catalogCtx = {requestId: 'catalog-req-001', category: 'hardware'};
    const rec = record0(catalogCtx);

    assert.equal(rec.requestId, 'catalog-req-001');
    assert.equal(rec.category, 'hardware');
    assert.equal(rec.label, 'record0:catalog-req-001');
    assert.equal(audit0('audit-cat'), 'audit0:audit-cat');
  });
});

